        PracticalGuideEntry("guide_12_selection", 12, "الاختيار بين الأنواع", "الإنتركم والكاميرات والداتا تختار كنظام متوافق؛ حدد فئة الوصلة والتدريع والطول والسرعة وميزانية تغذية PoE المطلوبة.", "Fluke: https://www.flukenetworks.com/knowledge-base/cableiq/verification-qualification-and-certification"),
        PracticalGuideEntry("guide_12_compatibility", 12, "توافق الخامات", "الكابل والكيستون والباتش بانل والباتش كورد يحكمون أداء الوصلة؛ التدريع يحتاج تفصيلته ولا يصلح بديلًا عن الفصل المناسب.", "Fluke: https://www.flukenetworks.com/knowledge-base/cableiq/verification-qualification-and-certification"),
        PracticalGuideEntry("guide_12_inspection", 12, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: اختبار ترتيب الأطراف لا يثبت السرعة؛ نفذ تأهيلًا أو اعتمادًا يناسب المطلوب، ثم اختبر الصورة ليلًا والصوت وفتح الباب وحفظ التسجيل.\n\nمتى تتوقف: توقف عند خط مجهول أو غذاء PoE غير كافٍ أو ترتيب أزواج غير صحيح أو بيانات دخول المصنع لم تتغير.", "Fluke: https://www.flukenetworks.com/knowledge-base/cableiq/verification-qualification-and-certification"),
        PracticalGuideEntry("guide_12_terms", 12, "أسماء السوق ومعناها", "الكيستون: قطعة إنهاء كابل. الباتش بانل: لوحة مخارج. PoE: تغذية عبر الشبكة. الواير ماب: فحص ترتيب واستمرارية الموصلات.", "Fluke: https://www.flukenetworks.com/knowledge-base/cableiq/verification-qualification-and-certification"),
        PracticalGuideEntry("guide_13_selection", 13, "الاختيار بين الأنواع", "السبليت والمخفي والكاسيت يحتاجون تأسيسًا مختلفًا؛ اختر الأقطار والأطوال والعزل والصرف وخلوص الهواء والخدمة من موديل الوحدة.", "دليل تركيب موديل التكييف والتهوية المركب"),
        PracticalGuideEntry("guide_13_compatibility", 13, "توافق الخامات", "النحاس والوصلات ومواد العزل والصرف والطلمبة توافق الوحدة؛ سيفون الضغط السالب لا يعمم على كل تكييف حائطي.", "دليل تركيب موديل التكييف والتهوية المركب"),
        PracticalGuideEntry("guide_13_inspection", 13, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: اختبر التسريب بالنيتروجين دون تجاوز حد المكونات، ثم التفريغ بإجراء الموديل؛ سجل ظروف الضغط، وافحص التكثيف والتصريف أثناء التشغيل.\n\nمتى تتوقف: توقف عند ماء داخل النحاس أو عزل مفتوح أو صرف محبوس أو ضغط اختبار أعلى من حد الجزء المختبر أو وحدة بلا مساحة خدمة.", "دليل تركيب موديل التكييف والتهوية المركب"),
        PracticalGuideEntry("guide_13_terms", 13, "أسماء السوق ومعناها", "الفلير: نهاية نحاس مفرودة لوصلة خاصة. الفاكيوم: تفريغ الدائرة بإجراءها. التكثيف: ماء يتكون على الأسطح الباردة. الدكت: قناة هواء.", "دليل تركيب موديل التكييف والتهوية المركب"),
        PracticalGuideEntry("guide_14_selection", 14, "الاختيار بين الأنواع", "اختَر الرشاش والكاشف والطفاية بحسب تصميم الخطر ونوع السقف والنظام؛ اللون أو نصف قطر واحد لا يحددان صلاحية التوزيع.", "التصميم المعتمد ودليل الرشاش والكاشف واللوحة ونظام سد الاختراق"),
        PracticalGuideEntry("guide_14_compatibility", 14, "توافق الخامات", "الكواشف والوحدات واللوحة متوافقة، وسد اختراق الحريق من تجميع مختبر يناسب الجدار والفتحة والخدمات لا أي فوم.", "التصميم المعتمد ودليل الرشاش والكاشف واللوحة ونظام سد الاختراق"),
        PracticalGuideEntry("guide_14_inspection", 14, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: اختبر الإنذار وعنوان الكاشف وسيناريو الربط والطوارئ بإجراء معتمد؛ شبكة الماء لها اختبارها، وتوثق الأعطال قبل الغلق.\n\nمتى تتوقف: توقف عند رشاش مدهون أو عائق يغير التغطية أو كاشف غير متوافق أو سد اختراق غير معتمد أو باب هروب لا يعمل.", "التصميم المعتمد ودليل الرشاش والكاشف واللوحة ونظام سد الاختراق"),
        PracticalGuideEntry("guide_14_terms", 14, "أسماء السوق ومعناها", "الحلقة: دائرة عنوانية وفق اللوحة. الزون: منطقة إنذار. الفاير ستوب: نظام سد اختراق يحافظ على التصنيف. K: معامل تدفق الرشاش بوحدته.", "التصميم المعتمد ودليل الرشاش والكاشف واللوحة ونظام سد الاختراق"),
        PracticalGuideEntry("guide_15_selection", 15, "الاختيار بين الأنواع", "اختر نظام اللصق من نوع ومقاس البلاط والركيزة والتعرض والحركة؛ سمك مشط المالج لا يساوي سمك اللاصق النهائي.", "Sika Egypt SikaCeram-30: https://egy.sika.com/en/construction/tiling/sikaceram-30.html"),
        PracticalGuideEntry("guide_15_compatibility", 15, "توافق الخامات", "اللاصق والغشاء والروبة والخلفية متوافقون؛ الروبة لا تغلق فاصل حركة، وتغطية الظهر لا تصلح لاصقًا غير مناسب.", "Sika Egypt SikaCeram-30: https://egy.sika.com/en/construction/tiling/sikaceram-30.html"),
        PracticalGuideEntry("guide_15_inspection", 15, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: ارفع عينة أثناء التركيب وافحص التغطية وزمن العمل؛ بعد المعالجة قِس الاستواء والتسنين والعراميس، والصوت وحده لا يحكم بالإزالة.\n\nمتى تتوقف: توقف عند قشرة لاصق جافة أو ركيزة ضعيفة أو فرق منسوب كبير يعوض بلاصق رقيق أو إلغاء فاصل الحركة.", "Sika Egypt SikaCeram-30: https://egy.sika.com/en/construction/tiling/sikaceram-30.html"),
        PracticalGuideEntry("guide_15_terms", 15, "أسماء السوق ومعناها", "التسنين: فرق منسوب حافتين متجاورتين. التسليخ: تغطية الظهر عندما يطلب النظام. السقية أو الروبة: ملء عراميس البلاط.", "Sika Egypt SikaCeram-30: https://egy.sika.com/en/construction/tiling/sikaceram-30.html"),
        PracticalGuideEntry("guide_16_selection", 16, "الاختيار بين الأنواع", "الحجر يختار من الامتصاص والمقاومة والعروق والتبقع والسمك والتثبيت؛ تشابه اللون لا يعني تساوي أداء صنفين.", "دليل الحجر والمثبتات؛ Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_16_compatibility", 16, "توافق الخامات", "لاصق وطلاء ظهر وحماية وسيلانت الحجر يختبرون معًا على عينة؛ سيليكون محايد عادي ليس ضمانًا لعدم التبقع.", "دليل الحجر والمثبتات؛ Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_16_inspection", 16, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: راجع الدفعة والعينة وتفاصيل الحوامل والأنكر وفحصها، ثم الاستواء والفواصل والتشطيب؛ اللمعان لا يثبت الحماية من البقع.\n\nمتى تتوقف: توقف عند حجر ضعيف حول الشق أو حامل مجهول التحمل أو طلاء ظهر غير متوافق أو فاصل حركة مملوء بمعجون صلب.", "دليل الحجر والمثبتات؛ Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_16_terms", 16, "أسماء السوق ومعناها", "الجولي: اسم سوق لمعجون حجر يحتاج تحديد نوعه. الجلي: تسوية وصقل. الكريستال: تلميع لبعض الأحجار. الكانة: جزء نظام التثبيت.", "دليل الحجر والمثبتات؛ Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_17_selection", 17, "الاختيار بين الأنواع", "HDF وSPC والباركيه الملصوق تختلف في الركيزة والرطوبة والطبقة السفلية والتأقلم والخدمة؛ لا تعمم فومًا أو زمنًا واحدًا.", "Quick-Step: https://int.quick-step.com/en/laminate/installation"),
        PracticalGuideEntry("guide_17_compatibility", 17, "توافق الخامات", "اختر اللاصق أو الطبقة السفلية وحاجز الرطوبة من موديل الأرضية والركيزة؛ ألواح بعازل مدمج قد تمنع إضافة فوم آخر.", "Quick-Step: https://int.quick-step.com/en/laminate/installation"),
        PracticalGuideEntry("guide_17_inspection", 17, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: قِس رطوبة الأسمنت أو الخشب بالطريقة المطلوبة لكل منهما، وافحص الاستواء والكليك وفواصل المحيط والانتقالات وحرية الأبواب.\n\nمتى تتوقف: توقف عند بلل مستمر أو خلفية ضعيفة أو كتم حركة الأرضية أو تلف الكليك؛ لا تعالج التقوس الدائم بالضغط بالقدم.", "Quick-Step: https://int.quick-step.com/en/laminate/installation"),
        PracticalGuideEntry("guide_17_terms", 17, "أسماء السوق ومعناها", "الكليك: وصلة تعشيق. الفوم: طبقة سفلية إذا سمح النظام. العتبة الانتقالية: تفصيلة لقاء تشطيبين دون حبس الحركة.", "Quick-Step: https://int.quick-step.com/en/laminate/installation"),
        PracticalGuideEntry("guide_18_selection", 18, "الاختيار بين الأنواع", "نظام الدهان يختار من الركيزة والرطوبة والقلوية والاستعمال واللمعة؛ عدد السكينات والأوجه يتبع التغطية والسمك المسموحين.", "نشرات البرايمر والمعجون والدهان ونموذج الاستلام"),
        PracticalGuideEntry("guide_18_compatibility", 18, "توافق الخامات", "البرايمر والمعجون والبطانة والتشطيب يتوافقون؛ لا يضاف ملون أو يخفف منتج بمذيب خارج نشرته، ولا يدهن فوق غبار الصنفرة.", "نشرات البرايمر والمعجون والدهان ونموذج الاستلام"),
        PracticalGuideEntry("guide_18_inspection", 18, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: اعتمد عينة، وافحص نظافة وجفاف وتماسك الركيزة ثم الالتصاق واللون واللمعة تحت إضاءة الاستلام المتفق عليها.\n\nمتى تتوقف: توقف عند مصدر رطوبة نشط أو أملاح عائدة أو طبقة ضعيفة أو دهان قديم غير متوافق؛ السيلر لا يصلح مصدر التسريب.", "نشرات البرايمر والمعجون والدهان ونموذج الاستلام"),
        PracticalGuideEntry("guide_18_terms", 18, "أسماء السوق ومعناها", "السكينة: طبقة فرد معجون. التلقيط: معالجة موضعية. البطانة: طبقة تجهيز للوجه التالي. السيلر: برايمر يختار لوظيفته.", "نشرات البرايمر والمعجون والدهان ونموذج الاستلام"),
        PracticalGuideEntry("guide_19_selection", 19, "الاختيار بين الأنواع", "نظام اللوح والشاسيه والمعلقات يختار من الأحمال والبحر وعدد الألواح والرطوبة والحريق؛ لون اللوح لا يثبت أداء التجميع.", "Knauf: https://knauf.com/en-EG/tools/download-center"),
        PracticalGuideEntry("guide_19_compatibility", 19, "توافق الخامات", "الشريط والمعجون والحواف وتسلسل الطبقات من نظام واحد؛ اختيار شريط آخر قد يتطلب معجونًا أو إجراءً مختلفًا.", "Knauf: https://knauf.com/en-EG/tools/download-center"),
        PracticalGuideEntry("guide_19_inspection", 19, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: راجع التثبيت والتدعيم قبل الغلق، ثم الاستواء والوصلات بعد الجفاف؛ تحقّق من الخدمة المستقلة للأحمال وفتحات الصيانة.\n\nمتى تتوقف: توقف عند معلقات غير مستلمة أو هيكل يتحرك أو ورق ممزق حول المسمار أو خدمات محملة على اللوح أو نظام حريق غير مكتمل.", "Knauf: https://knauf.com/en-EG/tools/download-center"),
        PracticalGuideEntry("guide_19_terms", 19, "أسماء السوق ومعناها", "الأوميجا والسي: قطاعات تختلف حسب النظام. التيش: عنصر تعليق وفق التفصيلة. شريط الفواصل: تسليح وصلة ضمن نظام المعجون.", "Knauf: https://knauf.com/en-EG/tools/download-center"),
        PracticalGuideEntry("guide_20_selection", 20, "الاختيار بين الأنواع", "الكرنيشة أو البانوه يختاران من مادتهما ووزنهما وشكل الركن والخلفية؛ اسم فيوتك لا يصف كل منتجات الزخرفة.", "دليل مادة الحلية ولاصق الخلفية والوصلات"),
        PracticalGuideEntry("guide_20_compatibility", 20, "توافق الخامات", "لاصق الخلفية ولاصق الوصلات ومعجون التشطيب يوافقون المادة؛ الجبس والبوليمر والخشب لا يتعاملون بوصفة واحدة.", "دليل مادة الحلية ولاصق الخلفية والوصلات"),
        PracticalGuideEntry("guide_20_inspection", 20, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: جرب ركنًا ووصلتين بعينة، وقِس زاوية الموقع الفعلية واستقامة الخط والتقاء الوصلات، ثم راجعها بعد زمن المعالجة.\n\nمتى تتوقف: توقف عند خلفية مفككة أو قطعة ثقيلة بلا نظام حمل أو قص لا يطابق زاوية الركن أو مادة لصق لا تقبلها الخامة.", "دليل مادة الحلية ولاصق الخلفية والوصلات"),
        PracticalGuideEntry("guide_20_terms", 20, "أسماء السوق ومعناها", "الكرنيشة: حلية أعلى الحائط. البانوه: إطار زخرفي. الوصلة: لقاء قطعتين تحتاج لصقًا وتسوية مناسبين.", "دليل مادة الحلية ولاصق الخلفية والوصلات"),
        PracticalGuideEntry("guide_21_selection", 21, "الاختيار بين الأنواع", "نظام الباب يختار من الوزن والأبعاد والاستعمال والحريق والرطوبة؛ المفصلة والغالق والقفل والحلق جزء من التجميع.", "جدول الباب ودليل الحلق والمفصلات والغالق والقفل"),
        PracticalGuideEntry("guide_21_compatibility", 21, "توافق الخامات", "المفصلة ومساميرها ومثبتات الحلق تناسب الضلفة والركيزة؛ الفوم ليس تثبيتًا إنشائيًا، وطلاء البيتومين لا يثبت حماية النمل الأبيض.", "جدول الباب ودليل الحلق والمفصلات والغالق والقفل"),
        PracticalGuideEntry("guide_21_inspection", 21, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: قِس الفتحة والحلق والخلوص والشاقولية، وجرب الفتح والإغلاق والتعشيق عبر الشوط؛ راجع وظيفة باب الحريق حسب اعتماده.\n\nمتى تتوقف: توقف عند حلق معوج أو مفصلة غير كافية أو خلوص يعوق الإغلاق أو تثبيت على طبقة ضعيفة أو تعديل يخرج باب الحريق عن نظامه.", "جدول الباب ودليل الحلق والمفصلات والغالق والقفل"),
        PracticalGuideEntry("guide_21_terms", 21, "أسماء السوق ومعناها", "الحلق الزفر: إطار تأسيس حسب نظام الباب. الضلفة: الجزء المتحرك. الكالون: جسم القفل. السلندر: جزء تشغيل المفتاح.", "جدول الباب ودليل الحلق والمفصلات والغالق والقفل"),
        PracticalGuideEntry("guide_22_selection", 22, "الاختيار بين الأنواع", "اختيار القطاع والزجاج من الأبعاد والرياح والماء والحرارة والصوت والأمان؛ الانعكاس أو بلد المنشأ لا يثبت الأداء.", "دليل القطاع والزجاج والجوان والمثبتات المركبة"),
        PracticalGuideEntry("guide_22_compatibility", 22, "توافق الخامات", "الزجاج والجوان وبلوك الارتكاز والسيليكون والإكسسوار والقطاع متوافقون؛ ختم الطقس يختلف عن لصق الزجاج الإنشائي.", "دليل القطاع والزجاج والجوان والمثبتات المركبة"),
        PracticalGuideEntry("guide_22_inspection", 22, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: افحص التثبيت والحركة والجوانات ومجاري التصريف، ثم نفذ اختبار ماء بإجراء الضغط والرش المحددين؛ لا تستنتج الصوت من الرش.\n\nمتى تتوقف: توقف عند فتحات تصريف مسدودة أو زجاج يلامس المعدن أو مثبت غير معتمد أو سيلانت غير متوافق أو ارتكاز زجاج ناقص.", "دليل القطاع والزجاج والجوان والمثبتات المركبة"),
        PracticalGuideEntry("guide_22_terms", 22, "أسماء السوق ومعناها", "القطاع: مقطع الإطار. الجوان: عنصر إحكام. السكاكة: جزء غلق بحسب النظام. بلوك الارتكاز: دعامة الزجاج داخل الإطار.", "دليل القطاع والزجاج والجوان والمثبتات المركبة"),
        PracticalGuideEntry("guide_23_selection", 23, "الاختيار بين الأنواع", "الطلاء والجرافيتو والحجر والكلادينج والبورسلين أنظمة واجهة مختلفة؛ الاختيار من الأحمال والحركة والحريق والطقس والركيزة.", "تفاصيل الواجهة واختبارات نظام الكسوة والعزل والحريق"),
        PracticalGuideEntry("guide_23_compatibility", 23, "توافق الخامات", "التثبيت والغشاء أو الخلفية وفواصل الحركة والختم والتصريف نظام واحد؛ طبقة دهان لا تثبت منع الماء خلف الكسوة.", "تفاصيل الواجهة واختبارات نظام الكسوة والعزل والحريق"),
        PracticalGuideEntry("guide_23_inspection", 23, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: راجع العينة ومثبتات الرياح وفواصل الكسوة والحواف ومخارج الماء؛ اختبار التثبيت والماء يحددان لكل تجميع قبل التنفيذ.\n\nمتى تتوقف: توقف عند تثبيت في خلفية ضعيفة أو مكونات حريق غير معتمدة أو فجوة تصريف مغلقة أو فاصل عامل مغلق بمادة صلبة.", "تفاصيل الواجهة واختبارات نظام الكسوة والعزل والحريق"),
        PracticalGuideEntry("guide_23_terms", 23, "أسماء السوق ومعناها", "الكلادينج: ألواح كسوة بتكوين محدد. الجرافيتو: تشطيب بنقشة حسب الصنف. قطرة المطر: تفصيلة قطع رجوع الماء أسفل الحافة.", "تفاصيل الواجهة واختبارات نظام الكسوة والعزل والحريق"),
        PracticalGuideEntry("guide_24_selection", 24, "الاختيار بين الأنواع", "الخزانة تختار من خامة اللوح وحماية الحواف والمفصلات والأدراج والحمل؛ مقاومة الرطوبة لا تعني تحمل غمر مستمر.", "أدلة الأجهزة والكاونتر والإكسسوارات ورسومات الوحدات"),
        PracticalGuideEntry("guide_24_compatibility", 24, "توافق الخامات", "الكاونتر وحامل الحوض واللاصق وفتحات الأجهزة متوافقون؛ لا يعتمد الحوض السفلي على مادة ختم فقط لحمله.", "أدلة الأجهزة والكاونتر والإكسسوارات ورسومات الوحدات"),
        PracticalGuideEntry("guide_24_inspection", 24, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: افحص توازي الوحدات والأدراج والتثبيت وخلوص المقابس والتهوية، ثم اختبر ملء وتفريغ الحوض والتسريب وتشغيل الأجهزة بإجرائها.\n\nمتى تتوقف: توقف عند كاونتر بلا تدعيم مطلوب أو تسريب على حواف مكشوفة أو جهاز بلا تهوية أو وحدة علوية مثبتة في خلفية غير صالحة.", "أدلة الأجهزة والكاونتر والإكسسوارات ورسومات الوحدات"),
        PracticalGuideEntry("guide_24_terms", 24, "أسماء السوق ومعناها", "الشاسيه: هيكل الوحدة. السوفت كلوز: إغلاق هادئ بالإكسسوار. HPL: كسوة، وليس وحده تعريف نوع اللوح الحامل.", "أدلة الأجهزة والكاونتر والإكسسوارات ورسومات الوحدات"),
        PracticalGuideEntry("guide_25_selection", 25, "الاختيار بين الأنواع", "موتور الشتر يختار من جدول العزم والوزن والمحور والاحتكاك ودورة التشغيل؛ المسار والستارة والموتور متوافقون.", "Somfy: https://www.somfy.com.eg/en-eg/assistance/downloads"),
        PracticalGuideEntry("guide_25_compatibility", 25, "توافق الخامات", "المجاري والشرائح والمحور والتحكم والطوارئ والفتحة القابلة للخدمة تجميعة واحدة؛ العزم بالنيوتن متر ليس قدرة بالوات.", "Somfy: https://www.somfy.com.eg/en-eg/assistance/downloads"),
        PracticalGuideEntry("guide_25_inspection", 25, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: افحص التوازي والخلوص، وجرب الاتجاه ونهايات الشوط والطوارئ ضمن زمن العمل والراحة؛ لا تكرر دورات تتجاوز حد الموتور.\n\nمتى تتوقف: توقف عند صوت احتكاك أو شرائح تخرج من المسار أو وصول صيانة مغلق أو توقف لا يفصل عند نهاية الحركة.", "Somfy: https://www.somfy.com.eg/en-eg/assistance/downloads"),
        PracticalGuideEntry("guide_25_terms", 25, "أسماء السوق ومعناها", "الدليل: مجرى حركة الشرائح. نهاية الشوط: حد الإيقاف. بيت الستارة: فراغ يحدد من المسارات والقماش والخدمة.", "Somfy: https://www.somfy.com.eg/en-eg/assistance/downloads"),
        PracticalGuideEntry("guide_26_selection", 26, "الاختيار بين الأنواع", "اختيار المعدن والزجاج والأنكر من الحمل والركيزة والبيئة والاحتجاز بعد الكسر؛ المغناطيس أو سمك زجاج واحد لا يثبت أمان الحاجز.", "تصميم الحاجز والمثبتات؛ BSSA: https://bssa.org.uk/bssa_articles/magnetic-properties-of-stainless-steel/"),
        PracticalGuideEntry("guide_26_compatibility", 26, "توافق الخامات", "المعدن والحماية واللحام والمسامير تتوافق مع البيئة؛ الزجاج ووسيلة قبضه وتدعيمه تجميعة مصممة، لا قطع مستقلة.", "تصميم الحاجز والمثبتات؛ BSSA: https://bssa.org.uk/bssa_articles/magnetic-properties-of-stainless-steel/"),
        PracticalGuideEntry("guide_26_inspection", 26, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: راجع شهادة الخام واللحامات والمثبتات والحواف، ثم اختبار حمل بإجراء واتجاه ونقطة وحد حركة معتمدين؛ لا تستبدله بالهز اليدوي.\n\nمتى تتوقف: توقف عند ركيزة متشققة أو أنكر مجهول أو زجاج غير مناسب لتفصيلة الأمان أو لحام معيب أو تثبيت يمس تسليحًا أو خدمات.", "تصميم الحاجز والمثبتات؛ BSSA: https://bssa.org.uk/bssa_articles/magnetic-properties-of-stainless-steel/"),
        PracticalGuideEntry("guide_26_terms", 26, "أسماء السوق ومعناها", "البلتة: صفيحة اتصال. الأنكر: مثبت في الركيزة بنوع محدد. التيش: قضيب ربط. الكوبستة: الجزء العلوي للحاجز.", "تصميم الحاجز والمثبتات؛ BSSA: https://bssa.org.uk/bssa_articles/magnetic-properties-of-stainless-steel/"),
        PracticalGuideEntry("guide_27_selection", 27, "الاختيار بين الأنواع", "اختر اللاصق أو السيلانت من الخامات والحركة والماء والشمس والحمل؛ اللاصق المرن لا يصبح تلقائيًا مثبتًا إنشائيًا.", "Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_27_compatibility", 27, "توافق الخامات", "اختبر التبقع والالتصاق والبرايمر والخلفية على عينة؛ بعض مواد الختم تصبغ الحجر أو لا تقبل الطلاء فوقها.", "Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_27_inspection", 27, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: قِس العرض والعمق وحبل الحشو، وافحص الاستمرار والالتصاق بعد تصلب العمق الفعلي؛ زمن تكون القشرة لا يساوي المعالجة الكاملة.\n\nمتى تتوقف: توقف عند فاصل رطب غير مسموح أو تلوث أو أبعاد خارج حدود المنتج أو التصاق بالخلفية يمنع حركة الفاصل.", "Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_27_terms", 27, "أسماء السوق ومعناها", "حبل الحشو: داعم يضبط العمق ويفصل الخلفية. السيلانت: ختم مرن. زمن القشرة: بداية السطح، وليس نهاية التصلب.", "Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("guide_28_selection", 28, "الاختيار بين الأنواع", "إكسسوار الشاور والمرايا والزجاج يختار من الوزن والتكوين والخلفية والماء؛ التصنيف والمثبتات أهم من النقش والشكل.", "أدلة الزجاج ومثبتات الشاور والمرآة والإكسسوارات"),
        PracticalGuideEntry("guide_28_compatibility", 28, "توافق الخامات", "لاصق المرآة وحشوات الزجاج والجوان والمفصلات مناسبة لنوع السطح؛ مواد حمضية أو غير متوافقة قد تتلف خلف المرآة.", "أدلة الزجاج ومثبتات الشاور والمرآة والإكسسوارات"),
        PracticalGuideEntry("guide_28_inspection", 28, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: راجع مواضع الخدمات قبل الثقوب، والتثبيت والحواف وحرية الحركة والإحكام؛ اختبر تشغيل الشاور وتسربه وفق تفصيلة الكابينة.\n\nمتى تتوقف: توقف عند محاولة ثقب زجاج مقسى أو مرآة غير مدعمة أو مثبت فوق خدمة مخفية أو مفصلة لا تناسب وزن الزجاج.", "أدلة الزجاج ومثبتات الشاور والمرآة والإكسسوارات"),
        PracticalGuideEntry("guide_28_terms", 28, "أسماء السوق ومعناها", "السيكوريت: زجاج مقسى. المصفح: زجاج بطبقة ترابط. الإكسسوار: جزء تثبيت أو حركة يحتاج تصنيفًا مناسبًا.", "أدلة الزجاج ومثبتات الشاور والمرآة والإكسسوارات"),
        PracticalGuideEntry("guide_29_selection", 29, "الاختيار بين الأنواع", "حدد لكل بند اختبارًا وأداة ونتيجة قبول قبل التنفيذ؛ قوة الأداة أو صورة المقياس لا تختصر إجراء الاستلام.", "إجراء الاختبار ومعايرة الأداة وحدود قبول النظام"),
        PracticalGuideEntry("guide_29_compatibility", 29, "توافق الخامات", "الجهاز ومداه ودقته ومعايرته يوافقون الجزء المختبر؛ لا يستخدم اختبار عزل أو ضغط يضر جهازًا موصولًا لم يعزل.", "إجراء الاختبار ومعايرة الأداة وحدود قبول النظام"),
        PracticalGuideEntry("guide_29_inspection", 29, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: سجل الجزء المعزول ونقطة القياس والوحدة والزمن والحرارة والنتيجة؛ عالج السبب وأعد الاختبار المتأثر قبل الغلق.\n\nمتى تتوقف: توقف عند جهاز بلا معايرة مطلوبة أو قراءات بلا وحدة أو قبول بلا حد أو أعمال مخفية لم تُفحص قبل تغطيتها.", "إجراء الاختبار ومعايرة الأداة وحدود قبول النظام"),
        PracticalGuideEntry("guide_29_terms", 29, "أسماء السوق ومعناها", "محضر الفحص: إجراء وقراءات وقرار موثق. المعايرة: مقارنة مرجعية للأداة. إعادة الفحص: تحقق بعد معالجة السبب.", "إجراء الاختبار ومعايرة الأداة وحدود قبول النظام"),
        PracticalGuideEntry("guide_30_selection", 30, "الاختيار بين الأنواع", "رتب الملاحظات من أثرها على الأمان والخدمة والتشطيب، وحدد المكان والوصف والمسؤول ومدة الإصلاح الواقعية.", "العقد ومحاضر الإصلاح والتسليم وأدلة التشغيل والضمان"),
        PracticalGuideEntry("guide_30_compatibility", 30, "توافق الخامات", "التنظيف والحماية وقطع الغيار وشروط الضمان تتوافق مع الخامة؛ مادة تنظيف واحدة قد تتلف أكثر من تشطيب.", "العقد ومحاضر الإصلاح والتسليم وأدلة التشغيل والضمان"),
        PracticalGuideEntry("guide_30_inspection", 30, "الفحص والقبول وإيقاف العمل", "طريقة الفحص: اختبر غرفة بغرفة وتحقق من إغلاق الملاحظة بإعادة الفحص؛ سلم مخطط الخدمات وأكواد الألوان والقطع وأدلة التشغيل والضمان الحقيقي.\n\nمتى تتوقف: توقف عن إغلاق التسليم عند عيب أمان أو تسريب نشط أو بند مخفي غير مستلم أو مستند لازم لم يكتمل.", "العقد ومحاضر الإصلاح والتسليم وأدلة التشغيل والضمان"),
        PracticalGuideEntry("guide_30_terms", 30, "أسماء السوق ومعناها", "السنّاج: ملاحظة تسليم محددة. المنفذ الفعلي: المسار والمقاس المنفذان، وليس الرسم القديم. الضمان: شروط تغطية فعلية من المورد.", "العقد ومحاضر الإصلاح والتسليم وأدلة التشغيل والضمان"),
        PracticalGuideEntry("example_tile_consumption", 15, "مثال موثق: استهلاك لاصق البلاط", "المثال للصنف SikaCeram-30 فقط: نشرة سيكا مصر تذكر تقريبًا 1.5 كجم/م² لكل 1 مم سمك نهائي لطبقة مصمتة. لمساحة 20 م² وسمك نهائي 4 مم: 20 × 4 × 1.5 = 120 كجم، أي 4 شكاير 30 كجم نظريًا. بافتراض هالك تقديري 10% تصبح 132 كجم، فتشتري 5 شكاير. الهالك افتراض للحساب، وليس رقم المصنع، والاستهلاك الفعلي يراجع بعينة؛ سمك سن المالج ليس السمك النهائي. النشرة تعطي حد طبقة مصمتة 3–6 مم لهذا الصنف، ولا يعمم على غيره.", "Sika Egypt SikaCeram-30: https://egy.sika.com/en/construction/tiling/sikaceram-30.html"),
        PracticalGuideEntry("example_tile_mixing", 15, "مثال موثق: ماء خلط الشيكارة", "SikaCeram-30 في نشرة سيكا مصر: 6 لتر ماء لكل شيكارة 30 كجم. اخلط بأداة بطيئة لا تتجاوز حد النشرة، واترك زمن الانتظار المحدد ثم أعد التقليب. هذه النسبة تخص الصنف والنشرة المعنيين؛ لا تستخدمها لكل لاصق ولا تضف ماءً بعد بدء الشك. الأرقام تراجع مع نشرة العبوة الموردة قبل التنفيذ.", "Sika Egypt SikaCeram-30: https://egy.sika.com/en/construction/tiling/sikaceram-30.html"),
        PracticalGuideEntry("example_slope_math", 6, "مثال حساب الميل", "إذا كان فرق المنسوب المفترض 40 مم على مسافة أفقية 3 م: حوّل المسافة إلى 3000 مم؛ الميل = 40 ÷ 3000 × 100 = 1.33%. هذا مثال للحساب وليس ميلًا إلزاميًا لكل سطح. تحدد مناسيب المصرف والعتبة وتفاوت التنفيذ وقطاع الطبقات أولًا.", "قطاع طبقات السقف والأحمال والمصارف المعتمد"),
        PracticalGuideEntry("example_sealant_volume", 27, "مثال كمية السيلانت", "لحساب حجم هندسي مفترض لفاصل: عرض 10 مم × عمق 6 مم × طول 10 م = 600 مل. خرطوشة افتراضية 300 مل تعطي خرطوشتين نظريًا قبل الهالك. هذه أبعاد افتراضية للحساب وليست تفصيلة تنفيذ أو نسبة عمق/عرض معتمدة؛ اختر أبعاد الفاصل الفعلية من حركة الفاصل وحدود السيلانت أولًا.", "Soudal: https://www.soudal.co.uk/pro/applications/sealing-joints/natural-stone-sealing"),
        PracticalGuideEntry("example_wall_area", 3, "مثال مساحة المحارة الصافية", "حائط مفترض عرضه 3.20 م وارتفاعه 2.80 م: المساحة 8.96 م². فتحة عرضها 0.90 م وارتفاعها 2.10 م: 1.89 م². المساحة الصافية الهندسية = 7.07 م². جوانب الفتحات تضاف إذا كانت ضمن العمل، وقواعد القياس التعاقدي قد تختلف. كمية الخامة من معدل نظام المحارة وسمكها وعينة التنفيذ، وليست من المساحة وحدها.", "نظام المحارة ومواصفة المشروع")
    )
}

fun EditableContentStore.apply(value: PracticalGuideEntry) = value.copy(title = text("guide", value.id, "title", value.title), body = text("guide", value.id, "body", value.body), source = text("guide", value.id, "source", value.source))
